solution.code:
type Getters<T> = {
  [K in keyof T as `get${Capitalize<string & K>}`]: () => T[K];
};

type User = { name: string; age: number };
type UserGetters = Getters<User>;

const keys = ['name', 'age'];
for (const k of keys) {
  console.log('get' + k[0].toUpperCase() + k.slice(1));
}

